<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\{Product,Brand,Industry,Document};use Illuminate\Http\Request;
class CatalogController extends Controller {public function products(Request $r){return Product::with(['brand','category'])->published()->search($r->q)->paginate(min((int)$r->get('per_page',20),100));}public function product(Product $product){abort_unless($product->status,404);return $product->load(['brand','category','images','attributes','documents','industries','applications']);}public function brands(){return Brand::where('status',1)->orderBy('name')->get();}public function industries(){return Industry::where('status',1)->orderBy('name')->get();}public function resources(Request $r){return Document::with(['brand','product'])->where('status',1)->when($r->type,fn($q)=>$q->where('document_type',$r->type))->paginate(30);}public function search(Request $r){$q=(string)$r->q;return ['products'=>Product::with('brand')->published()->search($q)->take(10)->get(),'brands'=>Brand::where('status',1)->where('name','like',"%{$q}%")->take(5)->get()];}}
